function mostFrequentChar(str) {
  const freq = {};
  for (const char of str) {
    if (char === ' ') continue;
    freq[char] = (freq[char] || 0) + 1;
  }
  let maxChar = '';
  let maxCount = 0;
  for (const char of str) {
    if (char === ' ') continue;
    if (freq[char] > maxCount) {
      maxCount = freq[char];
      maxChar = char;
    }
  }
  return maxChar;
}
